head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52100";
scwin.form = null;
scwin.upd_attachFiles = null;
scwin.upd_attachFiles_2 = null;
scwin.upd_attachFiles_3 = null;
scwin.upd_attachFiles_4 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles"]');
        scwin.upd_attachFiles_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_2"]');
        scwin.upd_attachFiles_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_3"]');
        scwin.upd_attachFiles_4 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_4') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_4"]');
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52100.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"searchType":"0"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — searchType, uploadCode, prtDepoNo

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_prtDepoReopnYn", fn: function(){ return ((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'); } }, { id: "c_otherwise_75", fn: function(){ return (!(((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'))); } }, { id: "if_searchType", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '0'); } }, { id: "txt_text89", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '1'); } }, { id: "btn_FileDown", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '1'); } }, { id: "if_searchType_3", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '2' || (dma_pageContext.get("searchType") ?? "") === '3'); } }, { id: "if_searchType_4", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '0'); } }, { id: "txt_text102", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '1'); } }, { id: "btn_FileDown_2", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '1'); } }, { id: "if_searchType_6", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '2' || (dma_pageContext.get("searchType") ?? "") === '3'); } }, { id: "btn_filePrtDepoWithd", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '4'); } }, { id: "btn_insertPrtDepoWithd", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '0'); } }, { id: "btn_updatePrtDepoWithd", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '2'); } }, { id: "btn_updatePrtDepoWithd_2", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "btn_FileDown", fn: function () { return String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "__rb1", fn: function () { return " 기 첨부된 파일 : " + String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "btn_FileDown_2", fn: function () { return String(dlt_attachList.getCellData(1, "attachFileNm")); } },
        { childId: "__rb2", fn: function () { return " 기 첨부된 파일 : " + String(dlt_attachList.getCellData(1, "attachFileNm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
    const prtDepoNo = (String(((dma_pageContext.get("prtDepoNo") ?? "")) == null ? '' : ((dma_pageContext.get("prtDepoNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("prtDepoNo") ?? "")) == null ? '' : ((dma_pageContext.get("prtDepoNo") ?? ""))));
    const searchType = (String(((dma_pageContext.get("searchType") ?? "")) == null ? '' : ((dma_pageContext.get("searchType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("searchType") ?? "")) == null ? '' : ((dma_pageContext.get("searchType") ?? ""))));
    if (searchType !== '' && searchType !== '0') {
        if (uploadCode === '0') {
            await $c.win.alert('저장되었습니다.');
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    if (prtDepoNo === '') {
                        await $c.win.alert('저장시 오류가 발생하였습니다.');
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prtDepoForm || { elements: [] });
        searchType = 'null';
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52100.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil52100' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

