/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    scwin.form = (document.prtDepoForm || { elements: [] });
    if (($c.util.getComponent('ipt_prtDepoWithdShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_prtDepoWithdShrs').getValue())) === '') {
        await $c.win.alert("처분주식수를 입력하십시오.");
        return false;
    }
    if (($c.util.getComponent('ipt_lstPrtDepoShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_lstPrtDepoShrs').getValue())) === '') {
        await $c.win.alert("최종의무보유주식수를 입력하십시오.");
        return false;
    }
    if (((!$c.util.getComponent('ipt_prtDepoReopnYn') || typeof $c.util.getComponent('ipt_prtDepoReopnYn').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_prtDepoReopnYn'), false) : ($c.util.getComponent('ipt_prtDepoReopnYn').getValue() != null && String($c.util.getComponent('ipt_prtDepoReopnYn').getValue()) !== '')) === true) {
        $c.util.getComponent("ipt_prtDepoReopnYn").setValue('Y');
        if (($c.util.getComponent('cal_prtDepoReopnDD').getValue() == null ? '' : String($c.util.getComponent('cal_prtDepoReopnDD').getValue())) === '') {
            await $c.win.alert('재의무보유일을 입력하십시오.');
            return false;
        }
    } else {
        $c.util.getComponent("ipt_prtDepoReopnYn").setValue('N');
    }
    return true;
};

/**
 * @method
 * @name insertPrtDepoWithd
 * @description insert Prt Depo Withd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insertPrtDepoWithd = async function () {
    scwin.form = (document.prtDepoForm || { elements: [] });
    scwin.form.action = '/listInvstg/prtDepo.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'write');
    if (($c.util.getComponent('upd_attachFiles').getValue() == null ? '' : String($c.util.getComponent('upd_attachFiles').getValue())) === '') {
        await $c.win.alert("처분신청 공문 관련 파일을 선택바랍니다.");
        return;
    }
    if (($c.util.getComponent('upd_attachFiles_3').getValue() == null ? '' : String($c.util.getComponent('upd_attachFiles_3').getValue())) === '') {
        await $c.win.alert("첨부서류을 선택바랍니다.");
        return;
    }
    if (await scwin.checkValue() === false) {
        return;
    }
    if (await $c.win.confirm('저장하시겠습니까?')) {
        const nr = await scwin.tx_insertPrtDepoWithd();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil52101/jldfil52101.xml", { "method": 'write' });
        }
    }
};

/**
