    }
};

/**
 * @method
 * @name sendPrtDepoWithd
 * @description send Prt Depo Withd 처리
 * @param {*} prtDepoNo prtDepoNo
 * @param {*} updateType updateType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendPrtDepoWithd = async function (prtDepoNo, updateType) {
    scwin.form = (document.prtDepoForm || { elements: [] });
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_FileDownReq').set('prtDepoNo', prtDepoNo);
        $c.util.getComponent('dma_FileDownReq').set('searchType', updateType);
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_FileDownReq').set('method', 'sendPrtDepoWithd');
        await scwin.tx_sendPrtDepoWithd();
    }
};

/**
